tasks.starter:
struct stask {
    int cls;       /* 0 deadline, 1 FIFO, 2 RR, 3 ordinary, 4 idle */
    long key;      /* deadline (deadline class) or priority (FIFO/RR) */
    long vr;       /* virtual time (ordinary) */
    int runnable;
};

int pick_next(const struct stask *t, int n) { (void)t; (void)n; return -1; }
